-- LOCAL PRO ONLY. Manual-opportunity follow-up + mixed read-only next contacts.
-- Existing request follow-ups and their exact receipts are never rewritten.
begin;
create table if not exists public.pro_lead_followups(owner_id uuid not null,lead_kind text not null default'manual'check(lead_kind='manual'),lead_id uuid not null,due_date date check(due_date between date'1900-01-01'and date'2100-12-31'),note text not null default''check(length(note)<=1000),status text not null default'open'check(status in('open','done')),revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,lead_id),foreign key(owner_id,lead_kind,lead_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade);
create index if not exists pro_lead_followups_due on pro_lead_followups(owner_id,due_date,lead_id)where status='open'and due_date is not null;
create table if not exists public.pro_lead_followup_history(owner_id uuid not null,lead_id uuid not null,action_id uuid not null,action text not null check(action in('save','complete','reopen')),before_followup jsonb,after_followup jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,lead_id)references pro_lead_followups(owner_id,lead_id)on delete cascade);
create index if not exists pro_lead_followup_history_page on pro_lead_followup_history(owner_id,lead_id,((after_followup->>'revision')::integer)desc);
create table if not exists public.pro_lead_followup_actions(owner_id uuid not null,action_id uuid not null,lead_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,lead_id)references pro_lead_followups(owner_id,lead_id)on delete cascade);
create or replace function public.pro_lead_followup_owner(p_actor uuid)returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql): hasProAccess plus the ban check.
 -- No public-directory/profile prerequisite.
 -- The service-only HTTP boundary separately checks admin MFA.
 perform public.pro_entitled_require(p_actor);end $$;
create or replace function public.pro_lead_followup_json(p_row pro_lead_followups,p_lead uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('leadId',p_lead,'dueDate',case when p_row.due_date is null then null else to_char(p_row.due_date,'YYYY-MM-DD')end,'note',coalesce(p_row.note,''),'status',coalesce(p_row.status,'open'),'revision',coalesce(p_row.revision,0),'updatedAt',p_row.updated_at)$$;
create or replace function public.pro_lead_followup_history_read(p_actor uuid,p_lead uuid,p_after uuid default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare rev integer;items jsonb;cursor_id uuid;begin
 perform pro_lead_followup_owner(p_actor);if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=p_lead)then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 if p_after is not null then select(after_followup->>'revision')::integer into rev from pro_lead_followup_history where owner_id=p_actor and lead_id=p_lead and action_id=p_after;if not found then raise exception'History cursor changed'using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(x.content order by x.revision desc),'[]')into items from(select(after_followup->>'revision')::integer revision,jsonb_build_object('actionId',action_id,'action',action,'at',at,'before',before_followup,'after',after_followup)content from pro_lead_followup_history where owner_id=p_actor and lead_id=p_lead and(p_after is null or(after_followup->>'revision')::integer<rev)order by(after_followup->>'revision')::integer desc limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_lead_followup_read(p_actor uuid,p_lead uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare f pro_lead_followups;h jsonb;archived boolean;begin
 perform pro_lead_followup_owner(p_actor);select l.archived into archived from pro_lead_center_records l where owner_id=p_actor and kind='manual'and id=p_lead;if not found then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 select * into f from pro_lead_followups where owner_id=p_actor and lead_id=p_lead;h:=pro_lead_followup_history_read(p_actor,p_lead);return jsonb_build_object('followup',pro_lead_followup_json(f,p_lead),'canWrite',not archived and exists(select 1 from pro_clients c join pro_lead_center_records l on l.owner_id=c.user_id and l.client_id=c.id and l.kind='manual'where l.owner_id=p_actor and l.id=p_lead and not c.archived),'history',h->'items','nextCursor',h->'nextCursor');end $$;
create or replace function public.pro_lead_followup_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_followup_actions;begin
 perform pro_lead_followup_owner(p_actor);select * into r from pro_lead_followup_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=r.lead_id)then raise exception'Opportunity unavailable'using errcode='42501';end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_followup_mutate(p_actor uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare lid uuid;aid uuid;act text;rev integer;f pro_lead_followups;r pro_lead_followup_actions;before_json jsonb;after_json jsonb;answer jsonb;due date;n text;archived boolean;has_followup boolean;client_archived boolean;begin
 perform pro_lead_followup_owner(p_actor);if jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['action','actionId','leadId','revision'])or jsonb_typeof(p_input->'action')is distinct from'string'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'leadId')is distinct from'string'or jsonb_typeof(p_input->'revision')is distinct from'number'or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false)or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception'Invalid follow-up'using errcode='22023';end if;
 act:=p_input->>'action';lid:=(p_input->>'leadId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if act='save'then
 if not(p_input?&array['dueDate','note'])or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','revision','dueDate','note']))or jsonb_typeof(p_input->'note')is distinct from'string'or jsonb_typeof(p_input->'dueDate')not in('null','string')then raise exception'Invalid follow-up fields'using errcode='22023';end if;
 n:=btrim(p_input->>'note');if length(n)>1000 then raise exception'Invalid note'using errcode='22023';end if;
 if p_input->'dueDate'<>'null'::jsonb then if not coalesce(p_input->>'dueDate'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false)then raise exception'Invalid date'using errcode='22023';end if;due:=(p_input->>'dueDate')::date;if due not between date'1900-01-01'and date'2100-12-31'or to_char(due,'YYYY-MM-DD')<>p_input->>'dueDate'then raise exception'Invalid date'using errcode='22023';end if;end if;
 elsif act in('complete','reopen')then if rev=0 or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','revision']))then raise exception'Invalid follow-up action'using errcode='22023';end if;
 else raise exception'Invalid action'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-followup-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-followup:'||p_actor::text||':'||lid::text,0));
 select l.archived into archived from pro_lead_center_records l where owner_id=p_actor and kind='manual'and id=lid for update;if not found then raise exception'Opportunity unavailable'using errcode='42501';end if;perform pro_lead_followup_owner(p_actor);
 select * into r from pro_lead_followup_actions where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception'Action identity reused'using errcode='22023';end if;return r.result;end if;
 select c.archived into client_archived from pro_clients c join pro_lead_center_records l on l.owner_id=c.user_id and l.client_id=c.id and l.kind='manual'where l.owner_id=p_actor and l.id=lid for update of c;perform pro_lead_followup_owner(p_actor);
 if archived or coalesce(client_archived,true)then raise exception'Restore the opportunity before editing its follow-up'using errcode='40001';end if;
 select * into f from pro_lead_followups where owner_id=p_actor and lead_id=lid for update;has_followup:=found;perform pro_lead_followup_owner(p_actor);
 if not has_followup then if act<>'save'or rev<>0 then raise exception'Follow-up changed'using errcode='40001';end if;insert into pro_lead_followups(owner_id,lead_id,due_date,note,status,revision)values(p_actor,lid,due,n,'open',1)returning*into f;
 else
 if rev<>f.revision then raise exception'Follow-up changed'using errcode='40001';end if;before_json:=pro_lead_followup_json(f,lid);
 if act='save'then update pro_lead_followups set due_date=due,note=n,revision=revision+1,updated_at=now()where owner_id=p_actor and lead_id=lid returning*into f;
 else if(act='complete'and f.status<>'open')or(act='reopen'and f.status<>'done')then raise exception'Invalid transition'using errcode='22023';end if;update pro_lead_followups set status=case when act='complete'then'done'else'open'end,revision=revision+1,updated_at=now()where owner_id=p_actor and lead_id=lid returning*into f;end if;end if;
 after_json:=pro_lead_followup_json(f,lid);answer:=jsonb_build_object('followup',after_json);insert into pro_lead_followup_history(owner_id,lead_id,action_id,action,before_followup,after_followup)values(p_actor,lid,aid,act,before_json,after_json);insert into pro_lead_followup_actions(owner_id,action_id,lead_id,input,result)values(p_actor,aid,lid,p_input,answer);perform pro_lead_followup_owner(p_actor);return answer;end $$;
create or replace function public.pro_lead_followups_upcoming(p_actor uuid,p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;begin
 perform pro_lead_followup_owner(p_actor);if(p_after is null)<>(p_snapshot is null)or(p_snapshot is not null and p_snapshot!~'^[0-9a-f]{32}$')then raise exception'Invalid pagination snapshot'using errcode='22023';end if;if p_after is not null and p_after!~'^(manual|request):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception'Invalid cursor'using errcode='22023';end if;
 with candidates as(
 select'manual'::text kind,f.lead_id id,f.due_date,f.note,f.status,f.revision,f.updated_at,l.title,c.name client_name from pro_lead_followups f join pro_lead_center_records l on l.owner_id=f.owner_id and l.kind='manual'and l.id=f.lead_id and not l.archived join pro_clients c on c.user_id=l.owner_id and c.id=l.client_id and not c.archived where f.owner_id=p_actor and f.status='open'and f.due_date is not null
 union all
 select'request',f.request_id,f.due_date,f.note,f.status,f.revision,f.updated_at,r.service,r.client_name from pro_request_followups f join pro_appointment_requests r on r.owner_id=f.owner_id and r.id=f.request_id left join pro_lead_center_records pref on pref.owner_id=f.owner_id and pref.kind='request'and pref.id=f.request_id where f.owner_id=p_actor and f.status='open'and f.due_date is not null and not coalesce(pref.archived,false)and not exists(select 1 from pro_clients c where c.user_id=p_actor and c.id='reservation-'||r.client_user_id::text and c.archived)
 ),metadata as(select md5(p_actor::text||(statement_timestamp()at time zone'America/Costa_Rica')::date::text||coalesce(jsonb_agg(jsonb_build_array(kind,id,due_date,revision,updated_at,title,client_name)order by due_date,kind,id)::text,'[]'))fingerprint from candidates),anchor as(select due_date,kind,id from candidates where kind||':'||id::text=p_after),page as(
 select c.* from candidates c where p_after is null or(c.due_date,c.kind,c.id)>(select a.due_date,a.kind,a.id from anchor a)order by c.due_date,c.kind,c.id limit 21
 ),encoded as(select kind,id,due_date,jsonb_build_object('kind',kind,'id',id,'dueDate',to_char(due_date,'YYYY-MM-DD'),'note',note,'status',status,'revision',revision,'updatedAt',updated_at,'title',title,'clientName',client_name)content from page)
 select jsonb_build_object('fingerprint',(select fingerprint from metadata),'asOfDayCR',to_char((statement_timestamp()at time zone'America/Costa_Rica')::date,'YYYY-MM-DD'),'summary',(select jsonb_build_object('open',count(*),'overdue',count(*)filter(where due_date<(statement_timestamp()at time zone'America/Costa_Rica')::date),'today',count(*)filter(where due_date=(statement_timestamp()at time zone'America/Costa_Rica')::date))from candidates),'items',coalesce((select jsonb_agg(content order by due_date,kind,id)from(select*from encoded order by due_date,kind,id limit 20)e),'[]'::jsonb),'nextCursor',case when(select count(*)from page)>20 then(select kind||':'||id::text from page order by due_date,kind,id offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from anchor))into answer;
 if p_snapshot is not null and p_snapshot is distinct from answer->>'fingerprint'then raise exception'Follow-up snapshot changed'using errcode='40001';end if;if not(answer->>'validCursor')::boolean then raise exception'Follow-up cursor changed'using errcode='40001';end if;return answer-'validCursor';end $$;
create or replace function public.pro_lead_followup_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception'Immutable follow-up audit'using errcode='23514';end $$;
drop trigger if exists pro_lead_followup_history_immutable on pro_lead_followup_history;
create trigger pro_lead_followup_history_immutable before update on pro_lead_followup_history for each row execute function pro_lead_followup_immutable();
drop trigger if exists pro_lead_followup_action_immutable on pro_lead_followup_actions;
create trigger pro_lead_followup_action_immutable before update on pro_lead_followup_actions for each row execute function pro_lead_followup_immutable();
alter table pro_lead_followups enable row level security;alter table pro_lead_followup_history enable row level security;alter table pro_lead_followup_actions enable row level security;
revoke all on pro_lead_followups,pro_lead_followup_history,pro_lead_followup_actions from public,anon,authenticated;grant all on pro_lead_followups,pro_lead_followup_history,pro_lead_followup_actions to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and(p.proname like'pro_lead_followup_%'or p.proname='pro_lead_followups_upcoming')loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';
